def closure(start, fds):
    found = set(start)
    changed = True
    while changed:
        changed = False
        for left, right in fds:
            if set(left) <= found and not set(right) <= found:
                found |= set(right)
                changed = True
    return found

fds = [(("student", "topic"), ("tutor",)), (("tutor",), ("topic",))]
assert closure(("tutor",), fds) == {"tutor", "topic"}
assert closure(("student", "topic"), fds) == {"student", "topic", "tutor"}
assert closure(("student", "tutor"), fds) == {"student", "topic", "tutor"}
assert closure(("student",), fds) == {"student"}
assert closure(("topic",), fds) == {"topic"}
assert len(closure(("student", "topic"), fds)) == 3
print(sorted(closure(("tutor",), fds)))
